mapper.select:
/* imageboard-mapper.xml id="selectImageBoardList" 이미지 게시판 목록 조회 */ SELECT seq , mb_id , title , writer_nm , image_url , thumb_url , DATE_FORMAT(in_dtm, '%Y-%m-%d %H:%i:%s') AS in_dtm , DATE_FORMAT(up_dtm, '%Y-%m-%d %H:%i:%s') AS up_dtm FROM tbts_image_board WHERE mb_id = #{mb_id} AND use_yn = 'Y'
AND title LIKE CONCAT('%', #{search_word}, '%')
ORDER BY seq DESC

mapper.insert:
/* imageboard-mapper.xml id="insertImageBoard" 이미지 게시판 등록 */
INSERT
  INTO tbts_image_board
     ( mb_id
     , title
     , writer_nm
     , image_url
     , thumb_url
     , use_yn
     , in_emp_cd
     , in_dtm
     )
VALUES
     ( #{mb_id}
     , #{title}
     , #{writer_nm}
     , #{image_url}
     , #{thumb_url}
     , 'Y'
     , #{in_emp_cd}
     , NOW()
     )

mapper.update:
/* imageboard-mapper.xml id="updateImageBoard" 이미지 게시판 수정 */
UPDATE tbts_image_board
   SET title     = #{title}
     , writer_nm = #{writer_nm}
     , image_url = #{image_url}
     , thumb_url = #{thumb_url}
     , up_emp_cd = #{up_emp_cd}
     , up_dtm    = NOW()
 WHERE mb_id = #{mb_id}
   AND seq   = #{seq}

mapper.delete:
/* imageboard-mapper.xml id="deleteImageBoard" 이미지 게시판 삭제(물리 삭제) */
DELETE FROM tbts_image_board
 WHERE mb_id = #{mb_id}
   AND seq   = #{seq}
